<?php require '../config.php';need_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM features WHERE id=?');$s->execute([$id]);$f=$s->fetch();if(!$f)exit('Not found');$c=db()->prepare('SELECT * FROM comments WHERE feature_id=? ORDER BY created_at DESC');$c->execute([$id]);$comments=$c->fetchAll();$flash=getflash();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review request</title><link rel="stylesheet" href="../assets/style.css"></head><body class="adminbody"><header class="adminnav"><div class="wrap nav"><a class="brand" href="index.php"><span class="mark">F</span> FeatureBoard Admin</a><nav class="links"><a href="../index.php">Public board</a><a href="logout.php">Log out</a></nav></div></header><main class="main"><div class="wrap"><a href="index.php">← Back to inbox</a><div class="detailgrid" style="margin-top:18px"><section><div class="panel"><div class="meta"><span class="status <?=e($f['status'])?>"><?=e(ucwords(str_replace('_',' ',$f['status'])))?></span><span class="pill"><?=e($f['category'])?></span></div><h1 style="font-family:'Space Grotesk';font-size:40px"><?=e($f['title'])?></h1><p style="line-height:1.7;color:#555"><?=nl2br(e($f['description']))?></p><hr style="border:0;border-top:1px solid var(--line)"><p><b>Submitted by:</b> <?=e($f['author_name'])?> · <?=e($f['author_email'])?></p><p><b>Votes:</b> <?=$f['votes']?> · <b>Created:</b> <?=date('M j, Y H:i',strtotime($f['created_at']))?></p></div><div class="panel" style="margin-top:16px"><h2>Customer discussion</h2><?php foreach($comments as $x):?><div class="comment"><b><?=e($x['name'])?></b> · <?=e($x['email'])?><p><?=nl2br(e($x['body']))?></p></div><?php endforeach;?><?php if(!$comments):?><p style="color:var(--muted)">No comments yet.</p><?php endif;?></div></section><aside><div class="panel"><h2>Update request</h2><form method="post" action="update.php"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><div class="field"><label>Status</label><select class="select" name="status"><?php foreach(['under_review','planned','in_progress','shipped','declined'] as $x):?><option value="<?=$x?>" <?=$f['status']===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach;?></select></div><div class="field"><label>Public team update</label><textarea name="response" rows="7" placeholder="Tell customers what changed…"><?=e($f['admin_response']??'')?></textarea></div><button class="btn orange">Save update</button></form></div><div class="panel" style="margin-top:16px"><h2>Internal action</h2><form method="post" action="delete.php" onsubmit="return confirm('Delete this request?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn ghost">Delete request</button></form></div></aside></div></div></main></body></html>
